import type { Metadata } from "next";
import { SITE, SITE_URL } from "@/lib/site";

/** 1200×630 share images, generated by `npm run og` (scripts/make-og.mjs). */
export const OG_IMAGES = {
  home: { url: "/og/home.jpg", alt: "Pack covers by John Swanson" },
  covers: { url: "/og/covers.jpg", alt: "Hip Hop, Funk and Heavy Electronic pack covers" },
  work: { url: "/og/work.jpg", alt: "Selected work by John Swanson" },
} as const;

type OgKey = keyof typeof OG_IMAGES;

/**
 * Per-page metadata with canonical URL, Open Graph and Twitter card.
 * Next merges openGraph shallowly, so each page sets the full object here.
 */
export function pageMeta({
  title,
  description,
  path,
  image = "home",
  absoluteTitle = false,
}: {
  title: string;
  description: string;
  path: string;
  image?: OgKey;
  absoluteTitle?: boolean;
}): Metadata {
  const og = OG_IMAGES[image];
  const fullTitle = absoluteTitle ? title : `${title} — ${SITE.name}`;
  const images = [{ url: og.url, width: 1200, height: 630, alt: og.alt }];
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE.name,
      url: `${SITE_URL}${path === "/" ? "" : path}`,
      title: fullTitle,
      description,
      images,
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [og.url],
    },
  };
}

/** Serialize JSON-LD safely for a <script> tag. */
export function jsonLd(data: unknown) {
  return { __html: JSON.stringify(data).replace(/</g, "\\u003c") };
}
